 32	export class LspClient {
 33	  public serverCmd: string;
 34	  public rootPath: string;
 35	  private child: ChildProcess | null = null;
 36	  private nextId: number = 1;
 37	  private pending: Map<number, { resolve: (val: any) => void; reject: (err: any) => void }> = new Map();
 38	  private diagnosticsMap: Map<string, LspDiagnostic[]> = new Map();
 39	  private buffer: string = "";
 40	  public initialized: boolean = false;
 41	
 42	  constructor(serverCmd: string, rootPath: string) {
 43	    this.serverCmd = serverCmd;
 44	    this.rootPath = path.resolve(rootPath);
 45	  }
 46	
 47	  public async start(): Promise<boolean> {
 48	    try {
 49	      this.child = spawn(this.serverCmd, [], {
 50	        cwd: this.rootPath,
 51	        stdio: ["pipe", "pipe", "pipe"],
 52	      });
 53	
 54	      this.child.on("error", () => {
 55	        this.initialized = false;
 56	      });
 57	
 58	      this.child.on("exit", () => {
 59	        this.initialized = false;
 60	      });
 61	
 62	      this.child.stdout?.on("data", (data: Buffer) => {
 63	        this.handleData(data.toString("utf-8"));
 64	      });
 65	
 66	      const rootUri = pathToFileURL(this.rootPath).href;
 67	
 68	      // 1. Initialize
 69	      const initRes = await this.sendRequest("initialize", {
 70	        processId: process.pid,
 71	        rootUri,
 72	        capabilities: {
 73	          textDocument: {
 74	            hover: { contentFormat: ["markdown", "plaintext"] },
 75	            definition: { dynamicRegistration: true },
 76	            publishDiagnostics: { relatedInformation: true },
 77	          },
 78	        },
 79	      }, 5000);
 80	
 81	      if (!initRes) return false;
 82	
 83	      // 2. Initialized notification
 84	      this.sendNotification("initialized", {});
 85	      this.initialized = true;
 86	      return true;
 87	    } catch {
 88	      this.initialized = false;
 89	      return false;
 90	    }
 91	  }
 92	
 93	  private handleData(chunk: string): void {
 94	    this.buffer += chunk;
 95	
 96	    while (true) {
 97	      const headerEnd = this.buffer.indexOf("\r\n\r\n");
 98	      if (headerEnd === -1) break;
 99	
100	      const header = this.buffer.slice(0, headerEnd);
101	      const match = header.match(/Content-Length:\s*(\d+)/i);
102	      if (!match) {
103	        this.buffer = this.buffer.slice(headerEnd + 4);
104	        continue;
105	      }
106	
107	      const contentLength = parseInt(match[1], 10);
108	      const bodyStart = headerEnd + 4;
109	
110	      if (this.buffer.length < bodyStart + contentLength) {
111	        // Incomplete body, wait for next chunk
112	        break;
113	      }
114	
115	      const body = this.buffer.slice(bodyStart, bodyStart + contentLength);
116	      this.buffer = this.buffer.slice(bodyStart + contentLength);
117	
118	      try {
119	        const msg = JSON.parse(body);
120	        if (msg.id !== undefined && this.pending.has(msg.id)) {
121	          const { resolve, reject } = this.pending.get(msg.id)!;
122	          this.pending.delete(msg.id);
123	          if (msg.error) {
124	            reject(new Error(msg.error.message || JSON.stringify(msg.error)));
125	          } else {
126	            resolve(msg.result);
127	          }
128	        } else if (msg.method === "textDocument/publishDiagnostics") {
129	          const params = msg.params;
130	          if (params && params.uri && Array.isArray(params.diagnostics)) {
185	      jsonrpc: "2.0",
186	      method,
187	      params,
188	    });
189	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
190	    this.child.stdin.write(header + payload);
191	  }
192	
193	  public notifyFileOpen(filePath: string, content: string, languageId: string): void {
194	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
195	    this.sendNotification("textDocument/didOpen", {
196	      textDocument: {
197	        uri,
198	        languageId,
199	        version: 1,
200	        text: content,
201	      },
202	    });
203	  }
204	
205	  public async getHover(filePath: string, line: number, character: number): Promise<string | null> {
206	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
207	    const res = await this.sendRequest("textDocument/hover", {
208	      textDocument: { uri },
209	      position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) },
210	    });
211	
212	    if (!res || !res.contents) return null;
213	
214	    if (typeof res.contents === "string") return res.contents;
215	    if (res.contents.value) return res.contents.value;
216	    if (Array.isArray(res.contents)) {
217	      return res.contents.map((c: any) => (typeof c === "string" ? c : c.value || "")).join("\n\n");
218	    }
219	    return JSON.stringify(res.contents);
220	  }
221	
222	  public async getDefinition(filePath: string, line: number, character: number): Promise<LspLocation[] | null> {
223	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
224	    const res = await this.sendRequest("textDocument/definition", {
225	      textDocument: { uri },
226	      position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) },
227	    });
228	
229	    if (!res) return null;
230	    if (Array.isArray(res)) return res;
231	    if (res.uri && res.range) return [res];
232	    return null;
233	  }
234	
235	  public getDiagnostics(filePath: string): LspDiagnostic[] {
236	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
237	    return this.diagnosticsMap.get(uri) || [];
238	  }
239	
240	  public shutdown(): void {
241	    if (this.child) {
242	      try {
243	        this.sendRequest("shutdown", {}).catch(() => {});
244	        this.sendNotification("exit", {});
245	        this.child.kill("SIGTERM");
246	      } catch {}
247	      this.child = null;
248	    }
249	    this.initialized = false;
250	  }
251	}
