253	/**
254	 * Manager to auto-route LSP queries based on file extension
255	 */
256	export class LspBridgeManager {
257	  private workspace: string;
258	  private clients: Map<string, LspClient> = new Map();
259	
260	  constructor(workspace: string) {
261	    this.workspace = path.resolve(workspace);
262	  }
263	
264	  public getServerForFile(filePath: string): { cmd: string; languageId: string } | null {
265	    const ext = path.extname(filePath).toLowerCase();
266	    if (ext === ".rs") {
267	      return { cmd: "rust-analyzer", languageId: "rust" };
268	    }
269	    if (ext === ".ts" || ext === ".tsx") {
270	      return { cmd: "typescript-language-server", languageId: "typescript" };
271	    }
272	    if (ext === ".js" || ext === ".jsx") {
273	      return { cmd: "typescript-language-server", languageId: "javascript" };
274	    }
275	    if (ext === ".py") {
276	      return { cmd: "pyright-langserver", languageId: "python" };
277	    }
278	    if (ext === ".go") {
279	      return { cmd: "gopls", languageId: "go" };
280	    }
281	    return null;
282	  }
283	
284	  public async getClientForFile(filePath: string): Promise<LspClient | null> {
285	    const serverInfo = this.getServerForFile(filePath);
286	    if (!serverInfo) return null;
287	
288	    if (this.clients.has(serverInfo.cmd)) {
289	      const client = this.clients.get(serverInfo.cmd)!;
290	      if (client.initialized) return client;
291	    }
292	
293	    const client = new LspClient(serverInfo.cmd, this.workspace);
294	    const ok = await client.start();
295	    if (ok) {
296	      this.clients.set(serverInfo.cmd, client);
297	      return client;
298	    }
299	    return null;
300	  }
301	
302	  public async hover(filePath: string, line: number, character: number): Promise<{ found: boolean; hoverText?: string; error?: string }> {
303	    const client = await this.getClientForFile(filePath);
304	    if (!client) {
305	      const info = this.getServerForFile(filePath);
306	      return {
307	        found: false,
308	        error: info ? `Language server '${info.cmd}' is not installed or failed to start.` : `No LSP server configured for ${filePath}.`,
309	      };
310	    }
311	
312	    try {
313	      const text = await client.getHover(filePath, line, character);
314	      return { found: Boolean(text), hoverText: text || "No hover documentation available." };
315	    } catch (err: any) {
316	      return { found: false, error: err.message };
317	    }
318	  }
319	
320	  public async definition(filePath: string, line: number, character: number): Promise<{ found: boolean; locations?: LspLocation[]; error?: string }> {
321	    const client = await this.getClientForFile(filePath);
322	    if (!client) {
323	      const info = this.getServerForFile(filePath);
324	      return {
325	        found: false,
326	        error: info ? `Language server '${info.cmd}' is not installed or failed to start.` : `No LSP server configured for ${filePath}.`,
327	      };
328	    }
329	
330	    try {
331	      const locations = await client.getDefinition(filePath, line, character);
332	      return { found: Boolean(locations && locations.length > 0), locations: locations || [] };
333	    } catch (err: any) {
334	      return { found: false, error: err.message };
335	    }
336	  }
337	
338	  public getDiagnostics(filePath: string): LspDiagnostic[] {
339	    const serverInfo = this.getServerForFile(filePath);
340	    if (!serverInfo || !this.clients.has(serverInfo.cmd)) return [];
341	    return this.clients.get(serverInfo.cmd)!.getDiagnostics(filePath);
342	  }
343	
344	  public shutdownAll(): void {
345	    for (const client of this.clients.values()) {
346	      client.shutdown();
347	    }
