     1	/**
     2	 * Nexus Code Automated Compiler & Test Diagnostic Recovery Engine
     3	 * Parses stderr/stdout from cargo, tsc, pytest, gcc, go, and test frameworks
     4	 * to provide structured error locations and actionable diagnostic hints.
     5	 */
     6	
     7	export interface Diagnostic {
     8	  file: string;
     9	  line?: number;
    10	  column?: number;
    11	  severity: "error" | "warning";
    12	  code?: string;
    13	  message: string;
    14	}
    15	
    16	/**
    17	 * Extracts compiler and test diagnostics from raw command output.
    18	 */
    19	export function extractCompilerDiagnostics(output: string): Diagnostic[] {
    20	  if (!output || typeof output !== "string") {
    21	    return [];
    22	  }
    23	
    24	  const diagnostics: Diagnostic[] = [];
    25	  const seen = new Set<string>();
    26	
    27	  const addDiag = (d: Diagnostic) => {
    28	    const key = `${d.file}:${d.line || 0}:${d.message}`;
    29	    if (!seen.has(key)) {
    30	      seen.add(key);
    31	      diagnostics.push(d);
    32	    }
    33	  };
    34	
    35	  // 1. Rust / cargo error parsing:
    36	  // error[E0308]: mismatched types
    37	  //  --> src/main.rs:12:5
    38	  const rustRegex = /error(?:\[(E\d+)\])?: ([^\n]+)\n\s+--> ([^\s:]+):(\d+):(\d+)/g;
    39	  let match: RegExpExecArray | null;
    40	  while ((match = rustRegex.exec(output)) !== null) {
    41	    addDiag({
    42	      code: match[1],
    43	      message: match[2].trim(),
    44	      file: match[3],
    45	      line: parseInt(match[4], 10),
    46	      column: parseInt(match[5], 10),
    47	      severity: "error",
    48	    });
    49	  }
    50	
    51	  // 2. TypeScript / tsc error parsing:
    52	  // src/index.ts:14:5 - error TS2322: Type 'number' is not assignable to type 'string'.
    53	  // or src/index.ts(14,5): error TS2322: ...
    54	  const tsRegex1 = /([^\s()]+\.(?:ts|tsx|js|jsx)):(\d+):(\d+) - (error|warning) (TS\d+): ([^\n]+)/g;
    55	  while ((match = tsRegex1.exec(output)) !== null) {
    56	    addDiag({
    57	      file: match[1],
    58	      line: parseInt(match[2], 10),
    59	      column: parseInt(match[3], 10),
    60	      severity: match[4] as "error" | "warning",
    61	      code: match[5],
    62	      message: match[6].trim(),
    63	    });
    64	  }
    65	
    66	  const tsRegex2 = /([^\s()]+\.(?:ts|tsx|js|jsx))\(([0-9]+),([0-9]+)\): (error|warning) (TS[0-9]+): ([^\n]+)/g;
    67	  while ((match = tsRegex2.exec(output)) !== null) {
    68	    addDiag({
    69	      file: match[1],
    70	      line: parseInt(match[2], 10),
    71	      column: parseInt(match[3], 10),
    72	      severity: match[4] as "error" | "warning",
    73	      code: match[5],
    74	      message: match[6].trim(),
    75	    });
    76	  }
    77	
    78	  // 3. Python / pytest traceback & test failures:
    79	  // FAILED tests/test_foo.py::test_bar - AssertionError: ...
    80	  const pytestRegex = /(?:FAILED|ERROR)\s+([^\s:]+\.py)(?:::(\S+))?\s*(?:-\s*([^\n]+))?/g;
    81	  while ((match = pytestRegex.exec(output)) !== null) {
    82	    addDiag({
    83	      file: match[1],
    84	      message: match[3] ? `${match[2] || "test"}: ${match[3].trim()}` : `Test failure in ${match[2] || match[1]}`,
    85	      severity: "error",
    86	    });
    87	  }
    88	
    89	  // Python Traceback line: File "foo.py", line 42, in ...
    90	  const pyTracebackRegex = /File "([^"]+\.py)", line (\d+)(?:, in [^\n]+)?\n\s*([^\n]+)\n\s*([A-Za-z]+Error: [^\n]+)/g;
    91	  while ((match = pyTracebackRegex.exec(output)) !== null) {
    92	    addDiag({
    93	      file: match[1],
    94	      line: parseInt(match[2], 10),
    95	      message: match[4].trim(),
    96	      severity: "error",
    97	    });
    98	  }
    99	
   100	  // 4. Standard GCC / Clang / Go error format:
   101	  // file.c:12:5: error: expected ';'
   102	  // file.go:12:5: undefined: foo
   103	  const genericRegex = /([^\s:]+\.[a-zA-Z0-9_]+):(\d+):(\d+):\s*(?:(error|warning):\s*)?([^\n]+)/g;
   104	  while ((match = genericRegex.exec(output)) !== null) {
   105	    // Avoid double-matching rust or ts lines
   106	    if (!match[1].endsWith(".rs") && !match[1].endsWith(".ts") && !match[1].endsWith(".tsx")) {
   107	      addDiag({
   108	        file: match[1],
   109	        line: parseInt(match[2], 10),
   110	        column: parseInt(match[3], 10),
   111	        severity: (match[4] === "warning" ? "warning" : "error"),
   112	        message: match[5].trim(),
   113	      });
   114	    }
   115	  }
   116	
   117	  // 5. Node.js AssertionError with stack trace
   118	  const nodeAssertRegex = /AssertionError(?: \[[^\]]+\])?: ([^\n]+)[\s\S]*?at [^\n]+ \(([^:]+\.(?:test|spec)\.[a-zA-Z0-9_]+):(\d+):(\d+)\)/;
   119	  const nodeMatch = nodeAssertRegex.exec(output);
   120	  if (nodeMatch) {
   121	    addDiag({
   122	      file: nodeMatch[2],
   123	      line: parseInt(nodeMatch[3], 10),
   124	      column: parseInt(nodeMatch[4], 10),
   125	      severity: "error",
   126	      message: `Assertion failure: ${nodeMatch[1].trim()}`,
   127	    });
   128	  }
   129	
   130	  return diagnostics;
   131	}
   132	
   133	/**
   134	 * Formats extracted diagnostics into clear, actionable hints for the agent context.
   135	 */
   136	export function formatDiagnosticHints(diagnostics: Diagnostic[]): string {
   137	  if (!diagnostics || diagnostics.length === 0) {
   138	    return "";
   139	  }
   140	
   141	  const lines = [
   142	    "\n\n[Automated Diagnostic Hints & Error Locations]:",
   143	    ...diagnostics.slice(0, 10).map((d) => {
   144	      const loc = d.line ? `:${d.line}${d.column ? `:${d.column}` : ""}` : "";
   145	      const code = d.code ? ` [${d.code}]` : "";
   146	      return `- ${d.file}${loc}${code}: ${d.message}`;
   147	    }),
   148	    "Tip: Use `read_file` or `edit_file` to inspect and fix the listed error locations.",
   149	  ];
   150	
